-- Repeat-safe grade/medium metadata additions; legacy rows remain NULL and visible.
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='notes' AND column_name='grade')=0,'ALTER TABLE notes ADD COLUMN grade VARCHAR(50) NULL, ADD COLUMN stream VARCHAR(100) NULL, ADD COLUMN medium VARCHAR(10) NULL, ADD INDEX idx_notes_grade(grade)','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='resources' AND column_name='grade')=0,'ALTER TABLE resources ADD COLUMN grade VARCHAR(50) NULL, ADD COLUMN stream VARCHAR(100) NULL, ADD COLUMN medium VARCHAR(10) NULL, ADD INDEX idx_resources_grade(grade)','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='quizzes' AND column_name='grade')=0,'ALTER TABLE quizzes ADD COLUMN grade VARCHAR(50) NULL AFTER topic, ADD COLUMN medium VARCHAR(10) NULL AFTER grade, ADD INDEX idx_quizzes_grade(grade)','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
SET @q=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='study_groups' AND column_name='grade')=0,'ALTER TABLE study_groups ADD COLUMN grade VARCHAR(50) NULL, ADD COLUMN subject VARCHAR(100) NULL, ADD COLUMN medium VARCHAR(10) NULL, ADD INDEX idx_groups_grade(grade), ADD INDEX idx_groups_subject(subject)','SELECT 1');PREPARE s FROM @q;EXECUTE s;DEALLOCATE PREPARE s;
